88	        setTagsDisponiveis((tagsResp.tags ?? []).filter((t) => !t.is_auto));
89	      })
90	      .catch((e) => setErro(e.message))
91	      .finally(() => setLoading(false));
92	  };
93	
94	  useEffect(() => { carregar(); }, []);
95	  useEffect(() => { if (moduloSalao) listarImpressoras().then(setImpressoras).catch(() => {}); }, [moduloSalao]);
96	
97	  const abrirNovo = () => {
98	    setEditando(null);
99	    setForm(EMPTY_FORM);
100	    setShowModal(true);
