6	// Gera o SVG do código de barras aqui no app principal (onde jsbarcode já está
7	// no bundle) e embute o markup pronto no HTML impresso — antes isso rodava
8	// dentro do iframe em branco carregando jsbarcode via <script src="cdn...">
9	// sem SRI; embutir o SVG já renderizado elimina a dependência de script
10	// externo (e o risco de supply chain) nesse fluxo por completo.
11	const renderBarcodeSvg = (id, value, displayText, opts = {}) => {
12	  const svgEl = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
13	  svgEl.setAttribute('id', id);
14	  JsBarcode(svgEl, value, {
15	    format: 'CODE128',
16	    width: opts.width ?? 2,
17	    height: opts.height ?? 56,
18	    displayValue: true,
19	    fontSize: opts.fontSize ?? 13,
20	    text: displayText,
21	    margin: opts.margin ?? 6,
22	    background: '#ffffff',
23	  });
24	  return new XMLSerializer().serializeToString(svgEl);
25	};
