// Cacheada porque o header do painel (menu lateral) monta 3 hooks que bateriam
// nessa rota em paralelo — cache-aside curto evita repetir as 3 queries a cada
// navegação entre páginas de /restaurante/*. Mesmo padrão do catálogo público
// (ver CatalogoController): sem invalidação manual, defasagem curta é aceitável.
async minhaEmpresa(userId: string) {
  const cacheKey = `restaurante:minha-empresa:${userId}`;
  const cached = await this.redis.getJSON<any>(cacheKey);
  if (cached) return cached;

  const resultado = await this.buscarMinhaEmpresa(userId);
  await this.redis.setJSON(cacheKey, resultado, TTL_MINHA_EMPRESA);
  return resultado;
}

private async buscarMinhaEmpresa(userId: string) {
  // payment_config nunca sai daqui em claro — tem rota própria mascarada
  // (GET /restaurante/config, ver getConfig() nesta mesma classe).
  const { data, error } = await this.supabase.client
    .from('restaurants')
    .select('id, name, address, state, city, neighborhood, cep, lat, lng, lat_ajustado_manualmente, logo_url, slug, custom_domain, custom_domain_status, custom_domain_motivo_recusa, business_hours, comissao_pct, type_id, modulo_delivery, modulo_salao, modulo_gdoor, auto_atendimento_habilitado, created_at')
    .eq('user_id', userId)
    .maybeSingle();

  if (error) throw error;
  if (!data) throw new NotFoundException('Nenhum restaurante vinculado');

  const { data: tipoRestaurante } = await this.supabase.client
    .from('establishment_types')
    .select('id')
    .eq('name', 'Restaurante')
    .maybeSingle();

  const { data: pedidosData } = await this.supabase.client
    .from('orders')
    .select('id, total, status')
    .eq('restaurant_id', data.id);

  const entregues = (pedidosData ?? []).filter((p) => p.status === 'delivered');
  const pendentes = (pedidosData ?? []).filter((p) =>
    ['pending', 'confirmed', 'ready', 'out_for_delivery'].includes(p.status),
  );
  const faturamento = entregues.reduce((acc, p) => acc + (p.total ?? 0), 0);

  return {
    empresa: { ...data, tipo_restaurante: data.type_id === tipoRestaurante?.id },
    metricas: {
      total_pedidos: pedidosData?.length ?? 0,
      pedidos_pendentes: pendentes.length,
      pedidos_entregues: entregues.length,
      faturamento,
    },
  };
}

